import { readFileSync } from 'node:fs';
export async function connect(port, renderer = false) {
  const targets = await (await fetch(`http://127.0.0.1:${port}/json/list`)).json();
  const target = renderer ? targets.find(t => t.type === 'page' && t.url.startsWith('http://localhost:4567')) : targets[0];
  if (!target) throw new Error('Expected debug target absent');
  const ws = new WebSocket(target.webSocketDebuggerUrl);
  await new Promise((resolve, reject) => { ws.onopen = resolve; ws.onerror = reject; });
  let seq = 0; const pending = new Map();
  ws.onmessage = e => { const m = JSON.parse(e.data); if (m.id && pending.has(m.id)) { const {resolve,reject,timer} = pending.get(m.id); clearTimeout(timer); pending.delete(m.id); m.error ? reject(new Error(JSON.stringify(m.error))) : resolve(m.result); } };
  const send = (method, params = {}) => new Promise((resolve,reject) => { const id = ++seq; const timer = setTimeout(() => {pending.delete(id); reject(new Error(`Timeout: ${method}`));},180000); pending.set(id,{resolve,reject,timer}); ws.send(JSON.stringify({id,method,params})); });
  if (renderer) {
    await send('Emulation.setFocusEmulationEnabled',{enabled:true});
    try { await send('Emulation.setPageVisibilityOverride',{visibility:'visible'}); } catch (e) { if (!e.message.includes("wasn't found")) throw e; }
  }
  return {send, close:() => ws.close(), eval: async expression => { const r = await send('Runtime.evaluate',{expression,awaitPromise:true,returnByValue:true}); if(r.exceptionDetails) throw new Error(JSON.stringify(r.exceptionDetails)); return r.result.value; }};
}
if (process.argv[1]?.endsWith('/cdp.mjs')) {
  const port = Number(process.argv[2]); const client = await connect(port,port===9676);
  try { console.log(JSON.stringify(await client.eval(readFileSync(process.argv[3],'utf8')),null,2)); } finally { client.close(); }
}

